/* From Uiverse.io by boryanakrasteva - Tags: button, delete */
.__UIV_SCOPE__ .btn {
  cursor: pointer;
  width: 50px;
  height: 50px;
  border: none;
  position: relative;
  border-radius: 10px;
  -webkit-box-shadow: 1px 1px 5px .2px #00000035;
  box-shadow: 1px 1px 5px .2px #00000035;
  -webkit-transition: .2s linear;
  transition: .2s linear;
  transition-delay: .2s;
  display: -webkit-box;
  display: -ms-flexbox;
  display: flex;
  -webkit-box-align: center;
  -ms-flex-align: center;
  align-items: center;
  -webkit-box-pack: center;
  -ms-flex-pack: center;
  justify-content: space-between;
}

.__UIV_SCOPE__ .btn:hover {
  width: 150px;
  transition-delay: .2s;
}

.__UIV_SCOPE__ .btn:hover > .paragraph {
  visibility: visible;
  opacity: 1;
  -webkit-transition-delay: .4s;
  transition-delay: .4s;
}

.__UIV_SCOPE__ .btn:hover > .icon-wrapper .icon {
  transform: scale(1.1);
}

.__UIV_SCOPE__ .bnt:hover > .icon-wrapper .icon path {
  stroke: black;
}

.__UIV_SCOPE__ .paragraph {
  color: black;
  visibility: hidden;
  opacity: 0;
  font-size: 18px;
  margin-right: 20px;
  padding-left: 20px;
  -webkit-transition: .2s linear;
  transition: .2s linear;
  font-weight: bold;
  text-transform: uppercase;
}

.__UIV_SCOPE__ .icon-wrapper {
  width: 50px;
  height: 50px;
  position: absolute;
  top: 0;
  right: 0;
  display: flex;
  align-items: center;
  justify-content: center;
}

.__UIV_SCOPE__ .icon {
  transform: scale(.9);
  transition: .2s linear;
}

.__UIV_SCOPE__ .icon path {
  stroke: #000;
  stroke-width: 2px;
  -webkit-transition: .2s linear;
  transition: .2s linear;
}
